links=[('01-settings-desktop.html','설정 현황'),('02-class-participants.html','참여자 표'),('03-mobile.html','모바일'),('04-states.html','예외 상태')]
def shell(title,body,file,cls=''):
    nav=''.join(f'<a href="{f}">{t}</a>' for f,t in links)
    html=f'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} · MIND BREEZE</title><style>{css}</style><body class="{cls}"><aside><strong>MIND BREEZE</strong><a href="01-settings-desktop.html">⌂ &nbsp; 홈</a><a class="{'active' if file.startswith('02') else ''}" href="02-class-participants.html">▦ &nbsp; 클래스 관리</a><a href="01-settings-desktop.html">▤ &nbsp; 리포트</a><a class="{'active' if not file.startswith('02') else ''}" href="01-settings-desktop.html">⚙ &nbsp; 설정</a><small>대구교육청 · 코치 웹<br>운영 화면 디자인 시안</small></aside><div class="topbar"><span>☰</span><span>MIND BREEZE</span><span>♧</span></div><main><div class="specimen">SDD-261 · 디자인 시안 / 모든 이름·건수·시각은 가상 예시 · 실제 저장 상태와 무관</div>{body}<div class="footer">시안 이동 · {nav.replace('</a>','</a> &nbsp; ')}<br>서버 수신 기준 예시 · 폰의 로컬 대기량은 확인할 수 없어요.</div></main><nav class="bottom"><a href="01-settings-desktop.html">⌂ 홈</a><a href="02-class-participants.html">▦ 클래스</a><a href="03-mobile.html">▤ 현황</a><a href="04-states.html">⚙ 설정</a></nav></body></html>'''
    (p/file).write_text(html)
