script='''<script>const data=ROWS;function render(){const q=document.getElementById('q').value.trim(),s=document.getElementById('status').value,g=document.getElementById('group').value;let a=data.filter(r=>r.name.includes(q)&&(!s||r.state===s));if(g==='name')a.sort((a,b)=>a.name.localeCompare(b.name,'ko'));let last='';document.getElementById('rows').innerHTML=a.map(r=>{let h='';if(g==='state'&&r.state!==last){last=r.state;h=`<tr class="group"><td colspan="7">${r.state} · ${a.filter(x=>x.state===r.state).length}명</td></tr>`}let icon=r.state==='완료'?'✓':r.state==='진행'?'◷':r.state==='확인 필요'?'!':'−';return h+`<tr><td><strong>${r.name}</strong></td><td>${r.feature===null?'미착용':'착용'}</td><td>${r.feature===null?'해당 없음':r.feature+' / 360'}</td><td>${r.raw===null?'해당 없음':r.raw+' / 180'}</td><td>${r.time}</td><td><span class="badge ${r.tone}">${icon} ${r.state}</span></td><td><button aria-expanded="false" aria-label="${r.name} 상세" onclick="let x=this.closest('tr').nextElementSibling;x.hidden=!x.hidden;this.setAttribute('aria-expanded',String(!x.hidden));this.textContent=x.hidden?'펼치기 ⌄':'접기 ⌃'">펼치기 ⌄</button></td></tr><tr hidden class="detail"><td colspan="7"><div class="detail-grid"><div><strong>서버 수신 기준</strong><p>${r.state==='완료'?'기대 범위 대조 완료 · 누락 없음':r.state==='미착용'?'EEG 수집 대상 아님 · 누락 아님':'기대 범위 대조 미완료'}</p></div><div><strong>${r.state==='확인 필요'?'! 영구 거절 · 격리':'폰 보고 기준'}</strong><p>${r.state==='확인 필요'?'원시 6청크 · 형식 검증 거절<br>자동 재시도 제외 · 운영자 확인 필요':'로컬 대기량 미확인<br>서버 수신량으로 추정하지 않아요.'}</p></div><div><strong>리포트 반영</strong><p>${r.state==='완료'?'feature 대조 완료 · 반영 가능':r.state==='미착용'?'EEG 없이 이용 가능':'feature 미완결 · EEG 반영 보류'}<br>원시는 리포트 입력과 별도 보관</p></div></div></td></tr>`}).join('');document.getElementById('result').textContent=`조회 결과 ${a.length}명`;document.getElementById('empty').hidden=!!a.length;}window.addEventListener('DOMContentLoaded',render);</script>'''.replace('ROWS',json.dumps(rows,ensure_ascii=False))
table='''<section class="card"><div class="toolbar"><label class="grow">참여자 이름<input id="q" placeholder="이름 검색" oninput="render()"></label><label>상태<select id="status" onchange="render()"><option value="">전체 상태</option><option>확인 필요</option><option>진행</option><option>완료</option><option>미착용</option></select></label><label>그룹핑<select id="group" onchange="render()"><option value="state">상태별</option><option value="name">이름순 · 그룹 없음</option></select></label></div></section><div class="line"><h2>참여자별 원데이터 업로드 현황</h2><p class="muted" id="result">조회 결과 40명</p></div><div class="tablewrap"><table><thead><tr><th scope="col">이름</th><th scope="col">착용</th><th scope="col">feature 창수</th><th scope="col">원시 청크</th><th scope="col">마지막 수신</th><th scope="col">상태</th><th scope="col">상세</th></tr></thead><tbody id="rows"></tbody></table><p id="empty" hidden style="padding:24px">검색 조건에 맞는 참여자가 없어요.</p></div>'''
